head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > tooltipLocaleRef]<br/>클라이언트 다국어가 적용되었을 때 tooltip 속성의 툴팁에 표시할 텍스트의 Key 값을 설정합니다.",
    "validation" : [
        "MultiSelect 컴포넌트에 tooltip 속성값이 없으면 부모 컴포넌트의 tooltipLocaleRef, useLocale 속성은 빈값이 됩니다.",
        "MultiSelect 컴포넌트에 useLocale=false 이면 부모 컴포넌트의 tooltipLocaleRef, useLocale 속성은 빈값이 됩니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 부모 그룹 DOM 의 속성 + tooltip 풍선 정보 출력 헬퍼
scwin.printParentInfo = function (targetName, parentDomQuery) {
    var pDom = document.querySelector(parentDomQuery);
    if (pDom) {
        wf_body_bottom.getObj("scwin").setReturnValue(targetName + " 부모 tooltip : '" + (pDom.getAttribute("tooltip") || "") + "'");
        wf_body_bottom.getObj("scwin").setReturnValue(targetName + " 부모 tooltipLocaleRef : '" + (pDom.getAttribute("tooltipLocaleRef") || "") + "'");
        wf_body_bottom.getObj("scwin").setReturnValue(targetName + " 부모 useLocale : '" + (pDom.getAttribute("useLocale") || "") + "'");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue(targetName + " 부모 그룹 DOM 미발견");
    }

    // tooltip 풍선 (hover 시점에만 표시되므로 null 안전 처리)
    var balloonLabel = document.querySelector('.w2balloonTip_label');
    var balloon = document.querySelector('.w2balloonTip');
    if (balloonLabel && balloon) {
        wf_body_bottom.getObj("scwin").setReturnValue("tooltip textContent : " + balloonLabel.textContent);
        wf_body_bottom.getObj("scwin").setReturnValue("tooltip display : " + balloon.style.display);
    }
};



// target1 (부모 그룹에 tooltip + tooltipLocaleRef + useLocale=true, 자식 multiselect 에 tooltip 미설정)
// 기대 동작: 자식의 tooltip 속성이 없으므로 부모 그룹의 tooltipLocaleRef, useLocale 속성이 빈값으로 변경됨
scwin.target1_onclick = function (e) {
    scwin.printParentInfo("target1", '[id$="grp_target1_parent"]');
};



// target2 (부모 그룹에 tooltip + tooltipLocaleRef + useLocale=true, 자식 multiselect 에 tooltip 설정 + useLocale=false)
// 기대 동작: 자식의 useLocale 이 false 이므로 부모 그룹의 tooltipLocaleRef, useLocale 속성이 빈값으로 변경됨
scwin.target2_onclick = function (e) {
    scwin.printParentInfo("target2", '[id$="grp_target2_parent"]');
};
